}

Method.Source:
public static void main(Args _args)
{
    DBMSysFlightingSyncController controller;
    controller = DBMSysFlightingSyncController::newFromArgs(_args);
    controller.startOperation();
}

protected void new(IdentifierName _className = classStr(DBMSysFlightingSyncService),
                    IdentifierName _methodName = methodStr(DBMSysFlightingSyncService, process),
                    SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    super(_className, _methodName, _executionMode);
}

public static DBMSysFlightingSyncController newFromArgs(Args _args)
{
    DBMSysFlightingSyncController controller;

    controller = new DBMSysFlightingSyncController();
    controller.parmArgs(_args);

    return controller;
}
